/** M0 structural snapshot from docs/api/openapi.yaml. Design artifact only.
 * Not a validator. Regenerate/reconcile at M1; OpenAPI remains authoritative. */
export type AdminUserCreateRequest = { "username": string; "password": string; "role": "analyst" | "admin"; };
export type AdminUserUpdateRequest = { "isActive"?: boolean; "role"?: "analyst" | "admin"; };
export type AnalysisCreateResponse = { "data": AnalysisRun; };
export type AnalysisRun = { "id": string; "datasetId": string; "family": "statistical" | "ml"; "method": string; "config": { [key: string]: unknown; }; "scope": NonNullable<DetectionRequest["scope"]>; "error"?: { "code": string; "message": string }; "status": "queued" | "running" | "completed" | "failed"; "createdAt": string; "completedAt"?: string; "engineVersion"?: string; "modelVersion"?: string; };
export type AnalysisRunPage = { "data": Array<AnalysisRun>; "page": PageInfo; };
export type Anomaly = { "id": string; "datasetId": string; "sensorId": string; "readingId": string; "analysisRunId": string; "ts": string; "location": { "type": "Point"; "coordinates": Array<number>; }; "family": "statistical" | "ml"; "method": string; "score": number; "severity": "low" | "medium" | "high"; "status": "open" | "confirmed" | "false_positive"; "note": string; "version": number; "updatedAt": string; };
export type AnomalyPage = { "data": Array<Anomaly>; "page": PageInfo; };
export type Dataset = { "id": string; "name": string; "sourceFilename": string; "status": "uploaded" | "awaiting_mapping" | "importing" | "imported" | "failed"; "createdBy": string; "createdAt": string; "importSummary"?: ImportSummary; };
export type DatasetPage = { "data": Array<Dataset>; "page": PageInfo; };
export type DetectionRequest = { "datasetId": string; "family": "statistical" | "ml"; "method": string; "config": { [key: string]: unknown; }; "scope"?: { "sensorIds"?: Array<string>; "from"?: string; "to"?: string; }; };
export type Error = { "error": { "code": string; "message": string; "details"?: { [key: string]: unknown; }; }; };
export type HealthResponse = { "status": "ok" | "degraded"; "timestamp": string; };
export type ImportIssue = { "rowNumber": number; "reason": "DUPLICATE_SAME_VALUE" | "DUPLICATE_VALUE_CONFLICT" | "INVALID_ROW"; "field"?: string; "keptRowNumber"?: number; };
export type ImportSummary = { "totalRows": number; "importedRows": number; "duplicateRows": number; "conflictingRows": number; "invalidRows": number; "issues": Array<ImportIssue>; };
export type LoginRequest = { "username": string; "password": string; };
export type LoginResponse = { "accessToken": string; "tokenType": "Bearer"; "user": UserPublic; };
export type MappingRequest = { "fieldMap": { "sensorId": string; "latitude": string; "longitude": string; "timestamp": string; "value": string; "unit"?: string; "name"?: string; "region"?: string; }; "unit": "ug/m3"; };
export type PageInfo = { "limit": number; "nextCursor": string | null; };
export type Reading = { "id": string; "datasetId": string; "sensorId": string; "ts": string; "location": { "type": "Point"; "coordinates": Array<number>; }; "value": number; "unit": "ug/m3"; };
export type ReadingPage = { "data": Array<Reading>; "page": PageInfo; };
export type ReviewChanges = { "status"?: "open" | "confirmed" | "false_positive"; "note"?: string; };
export type ReviewPatchRequest = { "baseVersion": number; "changes": ReviewChanges; };
export type Sensor = { "id": string; "datasetId": string; "externalId": string; "name": string; "location": { "type": "Point"; "coordinates": Array<number>; }; "type": "pm25"; "unit": "ug/m3"; "region"?: string; };
export type SensorPage = { "data": Array<Sensor>; "page": PageInfo; };
export type SingleAnomaly = { "data": Anomaly; };
export type SingleDataset = { "data": Dataset; };
export type UserPage = { "data": Array<UserPublic>; "page": PageInfo; };
export type UserPublic = { "id": string; "username": string; "role": "analyst" | "admin"; "isActive": boolean; };
export type UserResponse = { "data": UserPublic; };
export type ValidationReport = { "datasetId": string; "status": "uploaded" | "awaiting_mapping" | "importing" | "imported" | "failed"; "sourceColumns": Array<string>; "totalRows": number; "validRows": number; "invalidRows": number; "mappingSuggestions": { [key: string]: string; }; "issues": Array<ImportIssue>; };
export type DatasetsQuery = { "sort"?: "createdAt:asc" | "createdAt:desc"; "limit"?: number; "cursor"?: string; };
export type SensorsQuery = { "datasetId": string; "bbox"?: string; "sort"?: "externalId:asc" | "externalId:desc"; "limit"?: number; "cursor"?: string; };
export type ReadingsQuery = { "datasetId": string; "sensorId"?: string; "bbox"?: string; "from"?: string; "to"?: string; "sort"?: "ts:asc" | "ts:desc"; "limit"?: number; "cursor"?: string; };
export type AnalysisRunsQuery = { "datasetId": string; "sort"?: "createdAt:asc" | "createdAt:desc"; "limit"?: number; "cursor"?: string; };
export type AnomaliesQuery = { "datasetId": string; "analysisRunId"?: string; "status"?: "open" | "confirmed" | "false_positive"; "severity"?: "low" | "medium" | "high"; "family"?: "statistical" | "ml"; "method"?: string; "from"?: string; "to"?: string; "sort"?: "ts:asc" | "ts:desc"; "limit"?: number; "cursor"?: string; };
export type AdminUsersQuery = { "sort"?: "username:asc" | "username:desc"; "limit"?: number; "cursor"?: string; };
